package ru.zoldrax;

import com.google.gson.JsonParser;
import java.io.InputStreamReader;
import net.fabricmc.fabric.api.gametest.v1.FabricGameTest;
import net.minecraft.block.Blocks;
import net.minecraft.entity.EntityType;
import net.minecraft.entity.ItemEntity;
import net.minecraft.entity.passive.CowEntity;
import net.minecraft.item.*;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.screen.*;
import net.minecraft.screen.slot.SlotActionType;
import net.minecraft.test.*;
import net.minecraft.structure.StructurePlacementData;
import net.minecraft.util.*;
import net.minecraft.util.hit.BlockHitResult;
import net.minecraft.util.math.*;

/** Integration coverage for persistent state, real inventories and workstation rules. */
public final class TernorDecorTests implements FabricGameTest {
 private static final DecorKind[] KINDS={DecorKind.GARDEN_CANOPY,DecorKind.STORAGE_SHELF,DecorKind.ANIMAL_FEEDER,DecorKind.ANIMAL_TROUGH,DecorKind.STONE_FORGE,DecorKind.BELLOWS,DecorKind.QUENCHING_TUB};
 private void check(boolean value,String message){if(!value)throw new IllegalStateException(message);}
 private BlockPos root(TestContext c){return c.getAbsolutePos(new BlockPos(5,3,5));}
 private DecorBlockEntity place(TestContext c,DecorKind kind,BlockPos root){
  var player=c.createMockSurvivalPlayer();player.setPosition(Vec3d.ofCenter(root).add(0,0,4));player.setYaw(0);var stack=new ItemStack(DecorBlocks.BLOCKS.get(kind));player.setStackInHand(Hand.MAIN_HAND,stack);
  var hit=new BlockHitResult(Vec3d.ofCenter(root.down()).add(0,.5,0),Direction.UP,root.down(),false);
  check(((BlockItem)stack.getItem()).place(new ItemPlacementContext(player,Hand.MAIN_HAND,stack,hit)).isAccepted(),"Cannot place "+kind);
  player.discard();var entity=c.getWorld().getBlockEntity(root);check(entity instanceof DecorBlockEntity,"Missing root entity for "+kind);return (DecorBlockEntity)entity;
 }
 @GameTest(templateName="zoldrax_test:decor_arena") public void sevenModelsRecipesAndEditableSourcesExist(TestContext c){
  for(var kind:KINDS){check(c.getWorld().getRecipeManager().get(DecorBlocks.id(kind.id)).isPresent(),"Missing recipe "+kind);try(var model=getClass().getResourceAsStream("/assets/zoldrax/models/blockbench/decor/"+kind.id+".bbmodel")){check(model!=null,"Missing runtime model "+kind);var json=JsonParser.parseReader(new InputStreamReader(model)).getAsJsonObject();check(json.getAsJsonArray("elements").size()>=17,"Primitive model "+kind);check(json.getAsJsonArray("textures").get(0).getAsJsonObject().get("source").getAsString().startsWith("data:image/png;base64,"),"Non-editable texture "+kind);}catch(Exception ex){throw new RuntimeException(ex);}}
  try(var index=getClass().getResourceAsStream("/assets/zoldrax/ternor_display_models.json")){var json=JsonParser.parseReader(new InputStreamReader(index)).getAsJsonObject();check(json.size()==41,"Unexpected volumetric prop catalog size "+json.size());for(var entry:json.entrySet()){String name=entry.getValue().getAsJsonObject().get("model").getAsString();try(var prop=getClass().getResourceAsStream("/assets/zoldrax/models/blockbench/ternor_props/"+name+".bbmodel")){check(prop!=null,"Missing prop "+name);check(JsonParser.parseReader(new InputStreamReader(prop)).getAsJsonObject().getAsJsonArray("elements").size()>=3,"Flat prop "+name);}}}catch(Exception ex){throw new RuntimeException(ex);}c.complete();
 }
 @GameTest(templateName="zoldrax_test:decor_arena") public void canopyStoresOnlySupportedVolumetricPlants(TestContext c){
  var e=place(c,DecorKind.GARDEN_CANOPY,root(c));var p=c.createMockSurvivalPlayer();p.setPosition(Vec3d.ofCenter(e.getPos()).add(0,0,4));p.setStackInHand(Hand.MAIN_HAND,new ItemStack(Items.POPPY,4));e.use(p,Hand.MAIN_HAND);check(e.count(Items.POPPY)==1&&p.getMainHandStack().getCount()==3,"Plant insertion count wrong");p.setStackInHand(Hand.MAIN_HAND,new ItemStack(Items.CACTUS));e.use(p,Hand.MAIN_HAND);check(e.count(Items.CACTUS)==0,"Unsupported flat plant accepted");var copy=new DecorBlockEntity(e.getPos(),e.getCachedState());copy.readNbt(e.createNbt());check(copy.count(Items.POPPY)==1,"Canopy plant lost after reload");p.setStackInHand(Hand.MAIN_HAND,ItemStack.EMPTY);p.setSneaking(true);e.use(p,Hand.MAIN_HAND);check(e.isEmpty()&&p.getInventory().count(Items.POPPY)==1,"Canopy retrieval lost plant");var centre=e.getPos().add(1,0,1);check(c.getWorld().getBlockState(centre).getCollisionShape(c.getWorld(),centre).isEmpty(),"Canopy centre is not walkable");p.discard();c.complete();
 }
 @GameTest(templateName="zoldrax_test:decor_arena") public void shelfAndFeederUseRealPersistentInventories(TestContext c){
  var shelf=place(c,DecorKind.STORAGE_SHELF,root(c));check(shelf.size()==27,"Shelf is not 27 slots");shelf.setStack(0,new ItemStack(Items.IRON_INGOT,32));shelf.setStack(26,new ItemStack(Items.OAK_PLANKS,64));var copy=new DecorBlockEntity(shelf.getPos(),shelf.getCachedState());copy.readNbt(shelf.createNbt());check(copy.count(Items.IRON_INGOT)==32&&copy.count(Items.OAK_PLANKS)==64,"Shelf NBT lost contents");c.getWorld().removeBlock(shelf.getPos(),false);
  var feeder=place(c,DecorKind.ANIMAL_FEEDER,root(c));check(feeder.size()==9&&feeder.isValid(0,new ItemStack(Items.WHEAT))&&!feeder.isValid(0,new ItemStack(Items.DIAMOND)),"Feeder filter wrong");for(int i=0;i<9;i++)feeder.setStack(i,new ItemStack(Items.WHEAT,64));check(BasketDisplayLayout.create(feeder).size()==36,"Full feeder has sparse display");var player=c.createMockCreativeServerPlayerInWorld();player.setPosition(Vec3d.ofCenter(feeder.getPos()).add(0,0,3));feeder.use(player,Hand.MAIN_HAND);check(player.currentScreenHandler instanceof Generic3x3ContainerScreenHandler,"Feeder GUI missing");player.closeHandledScreen();player.discard();c.complete();
 }
 @GameTest(templateName="zoldrax_test:decor_arena") public void feederConsumesFeedWithoutForcedBreeding(TestContext c){
  var e=place(c,DecorKind.ANIMAL_FEEDER,root(c));e.setStack(0,new ItemStack(Items.WHEAT,2));var cow=EntityType.COW.create(c.getWorld());check(cow!=null,"Cannot create cow");var target=DecorBlocks.point(e.getPos(),e.getCachedState().get(DecorBaseBlock.FACING),1,0,1.4);cow.refreshPositionAndAngles(target.x,target.y,target.z,0,0);check(c.getWorld().spawnEntity(cow),"Cannot spawn cow");check(e.ternor.careForAnimals(c.getWorld()),"Nearby cow was not fed");check(e.count(Items.WHEAT)==1&&!cow.isInLove(),"Feeder bred animal or used wrong amount");check(!e.ternor.careForAnimals(c.getWorld()),"Animal cooldown ignored");var saved=e.createNbt();var copy=new DecorBlockEntity(e.getPos(),e.getCachedState());copy.readNbt(saved);check(!copy.ternor.careForAnimals(c.getWorld()),"Animal cooldown did not persist");cow.discard();c.complete();
 }
 @GameTest(templateName="zoldrax_test:decor_arena") public void troughHasFourSavedLevelsAndReturnsBucket(TestContext c){
  var e=place(c,DecorKind.ANIMAL_TROUGH,root(c));var p=c.createMockSurvivalPlayer();p.setPosition(Vec3d.ofCenter(e.getPos()).add(0,0,3));p.setStackInHand(Hand.MAIN_HAND,new ItemStack(Items.WATER_BUCKET));e.use(p,Hand.MAIN_HAND);check(e.ternor.water==4&&p.getMainHandStack().isOf(Items.BUCKET),"Water bucket transaction wrong");e.ternor.water=2;e.changed();var copy=new DecorBlockEntity(e.getPos(),e.getCachedState());copy.readNbt(e.createNbt());check(copy.ternor.water==2,"Water level did not persist");var cow=EntityType.COW.create(c.getWorld());var target=DecorBlocks.point(e.getPos(),e.getCachedState().get(DecorBaseBlock.FACING),1,0,1.4);cow.refreshPositionAndAngles(target.x,target.y,target.z,0,0);c.getWorld().spawnEntity(cow);check(e.ternor.careForAnimals(c.getWorld())&&e.ternor.water==1,"Animal did not drink exactly one level");check(!e.ternor.careForAnimals(c.getWorld()),"Trough cooldown ignored");cow.discard();p.discard();c.complete();
 }
 @GameTest(templateName="zoldrax_test:decor_arena") public void forgeUsesVanillaRepairAndSmeltingRules(TestContext c){
  var e=place(c,DecorKind.STONE_FORGE,root(c));var p=c.createMockCreativeServerPlayerInWorld();p.changeGameMode(net.minecraft.world.GameMode.SURVIVAL);p.experienceLevel=30;p.setPosition(Vec3d.ofCenter(e.getPos()).add(0,0,3));e.use(p,Hand.MAIN_HAND);check(p.currentScreenHandler instanceof AnvilScreenHandler,"Forge repair UI is not anvil-compatible");var anvil=(AnvilScreenHandler)p.currentScreenHandler;var sword=new ItemStack(Items.IRON_SWORD);sword.setDamage(180);anvil.getSlot(0).setStack(sword);anvil.getSlot(1).setStack(new ItemStack(Items.IRON_INGOT,2));check(!anvil.getSlot(2).getStack().isEmpty()&&anvil.getLevelCost()>0,"Repair has no material/XP cost");anvil.onSlotClick(2,0,SlotActionType.PICKUP,p);check(e.ternor.workTicks==40&&anvil.getSlot(1).getStack().getCount()<2&&p.experienceLevel<30,"Repair did not consume material/XP or animate");p.closeHandledScreen();p.setSneaking(true);e.use(p,Hand.MAIN_HAND);check(p.currentScreenHandler instanceof FurnaceScreenHandler,"Forge smelting UI missing");p.closeHandledScreen();p.discard();c.complete();
 }
 @GameTest(templateName="zoldrax_test:decor_arena",tickLimit=360) public void bellowsBoostOnlyAfterManualCycleAndIsCapped(TestContext c){
  var forge=place(c,DecorKind.STONE_FORGE,root(c));var bellows=place(c,DecorKind.BELLOWS,root(c).east(3));forge.setStack(0,new ItemStack(Items.IRON_INGOT,2));forge.setStack(1,new ItemStack(Items.COAL,2));
  c.waitAndRun(100,()->{int before=forge.ternor.cook;check(before>=80&&before<=120&&forge.getStack(2).isEmpty(),"Forge was passively boosted");var p=c.createMockSurvivalPlayer();p.setPosition(Vec3d.ofCenter(bellows.getPos()).add(0,0,3));bellows.use(p,Hand.MAIN_HAND);bellows.use(p,Hand.MAIN_HAND);check(bellows.ternor.workTicks==200,"Bellows boost stacked instead of refreshing");p.discard();c.waitAndRun(80,()->{check(!forge.getStack(2).isEmpty(),"Manual bellows did not accelerate forge");check(bellows.ternor.workTicks<200&&bellows.ternor.workTicks>0,"Bellows timer not bounded");c.complete();});});
 }
 @GameTest(templateName="zoldrax_test:decor_arena") public void hotMetalQuenchesByDataRecipeAndConsumesWater(TestContext c){
  var e=place(c,DecorKind.QUENCHING_TUB,root(c));e.ternor.water=4;var p=c.createMockSurvivalPlayer();p.setPosition(Vec3d.ofCenter(e.getPos()).add(0,0,3));p.setStackInHand(Hand.MAIN_HAND,new ItemStack(Items.IRON_INGOT));check(!e.ternor.quench(p,Hand.MAIN_HAND),"Cold ingot quenched");var hot=new ItemStack(Items.IRON_INGOT,2);hot.getOrCreateNbt().putLong("TernorHotUntil",c.getWorld().getTime()+600);p.setStackInHand(Hand.MAIN_HAND,hot);check(e.ternor.quench(p,Hand.MAIN_HAND),"Hot ingot recipe failed");check(e.ternor.water==3&&p.getMainHandStack().getCount()==1&&p.getInventory().getMainHandStack().getNbt().getLong("TernorHotUntil")>0,"Quench consumed wrong input/water");check(p.getInventory().count(Items.IRON_INGOT)==2,"Quench lost or duplicated result");boolean tempered=false;for(int i=0;i<p.getInventory().size();i++){var stack=p.getInventory().getStack(i);if(stack.hasNbt()&&stack.getNbt().getBoolean("TernorTempered"))tempered=true;}check(tempered,"Recipe output lacks tempered marker");var copy=new DecorBlockEntity(e.getPos(),e.getCachedState());copy.readNbt(e.createNbt());check(copy.ternor.water==3,"Tub level did not persist");p.discard();c.complete();
 }
 @GameTest(templateName="zoldrax_test:decor_arena",tickLimit=100) public void breakingShelfDropsOneBlockAndAllContents(TestContext c){
  var e=place(c,DecorKind.STORAGE_SHELF,root(c));e.setStack(0,new ItemStack(Items.DIAMOND,17));e.setStack(1,new ItemStack(Items.IRON_INGOT,9));var part=e.getPos().add(DecorBlocks.offset(e.kind,1,e.getCachedState().get(DecorBaseBlock.FACING)));c.getWorld().breakBlock(part,true);c.waitAndRun(2,()->{var drops=c.getWorld().getEntitiesByClass(ItemEntity.class,new Box(e.getPos()).expand(6),x->true);check(drops.stream().filter(x->x.getStack().isOf(DecorBlocks.BLOCKS.get(DecorKind.STORAGE_SHELF).asItem())).mapToInt(x->x.getStack().getCount()).sum()==1,"Shelf block duplicated/lost");check(drops.stream().filter(x->x.getStack().isOf(Items.DIAMOND)).mapToInt(x->x.getStack().getCount()).sum()==17,"Shelf contents lost");check(drops.stream().filter(x->x.getStack().isOf(Items.IRON_INGOT)).mapToInt(x->x.getStack().getCount()).sum()==9,"Shelf contents duplicated");c.complete();});
 }
 @GameTest(templateName=EMPTY_STRUCTURE,tickLimit=200) public void settlementTemplatesRotateWithCompleteMultiblocks(TestContext c){
  var expected=java.util.Map.of("workshop",3,"farmyard",3,"storehouse",1);var origin=c.getAbsolutePos(new BlockPos(8,4,8));
  for(var entry:expected.entrySet())for(var rotation:BlockRotation.values()){var template=c.getWorld().getStructureTemplateManager().getTemplate(DecorBlocks.id("ternor/"+entry.getKey())).orElseThrow();var data=new StructurePlacementData().setRotation(rotation).setIgnoreEntities(true);var bounds=template.calculateBoundingBox(data,origin);check(template.place(c.getWorld(),origin,origin,data,net.minecraft.util.math.random.Random.create(7),3),"Cannot place "+entry.getKey()+" "+rotation);int roots=0;
   for(var pos:BlockPos.iterate(bounds.getMinX(),bounds.getMinY(),bounds.getMinZ(),bounds.getMaxX(),bounds.getMaxY(),bounds.getMaxZ()))if(c.getWorld().getBlockEntity(pos) instanceof DecorBlockEntity e){roots++;for(int i=0;i<e.kind.cells(1);i++){var cell=e.getPos().add(DecorBlocks.offset(e.kind,i,e.getCachedState().get(DecorBaseBlock.FACING)));var cellState=c.getWorld().getBlockState(cell);check(cellState.getBlock() instanceof DecorBaseBlock,"Missing template part "+i+" of "+e.kind+" "+rotation+" at "+cell.toShortString()+" root="+e.getPos().toShortString()+" facing="+e.getCachedState().get(DecorBaseBlock.FACING));check(DecorBlocks.entity(c.getWorld(),cell,cellState)==e,"Wrong template root "+i+" of "+e.kind+" "+rotation);}}
   check(roots==entry.getValue(),"Wrong workstation count in "+entry.getKey()+" "+rotation+": "+roots);for(var pos:BlockPos.iterate(bounds.getMinX(),bounds.getMinY(),bounds.getMinZ(),bounds.getMaxX(),bounds.getMaxY(),bounds.getMaxZ()))c.getWorld().setBlockState(pos,Blocks.AIR.getDefaultState(),2);
  }c.complete();
 }
 @GameTest(templateName="zoldrax_test:decor_arena") public void futureNpcApiMovesOnlyValidSupplies(TestContext c){
  var feeder=place(c,DecorKind.ANIMAL_FEEDER,root(c));var wheat=new ItemStack(Items.WHEAT,8);check(TernorWorkstationApi.insert(c.getWorld(),feeder.getPos(),wheat,3)==3&&wheat.getCount()==5&&feeder.count(Items.WHEAT)==3,"NPC feed insertion failed");var stone=new ItemStack(Items.STONE,4);check(TernorWorkstationApi.insert(c.getWorld(),feeder.getPos(),stone,4)==0&&stone.getCount()==4,"NPC API bypassed feed filter");c.getWorld().removeBlock(feeder.getPos(),false);var trough=place(c,DecorKind.ANIMAL_TROUGH,root(c));check(TernorWorkstationApi.fillWater(c.getWorld(),trough.getPos(),2)==2&&trough.ternor.water==2,"NPC water API failed");c.complete();
 }
}
